// Swiftee's diving mask (as in Fishing Frenzy's lesson): drawn on every frame of every pose by js/costume.js,
// registered to her eyes by mask-anchors.js ([cx, cy, spread, r, angle] per frame, fractions of the cell; generated by
// Fishing Frenzy's tools/build-mask-anchors.py from the same sprite sheets).
// A pair of rounded lenses in a sunny-yellow silicone frame with a darker rim, joined by a bridge over her beak, with
// tinted glass her eyes show through, a curved glare on each lens, a soft contact shadow on her face, a strap that
// wraps round her head (drawn only over her own pixels, so it never floats past her outline) and a little snorkel.
(function () {
  const TAU = Math.PI * 2;
  const rr = (c, x, y, w, h, r) => { c.beginPath(); c.roundRect(x, y, w, h, r); };
  // a lens's frame as a ring (outer outline minus its glass), so the eye under the glass is never painted over
  // the mask's one-piece silicone body: one outline round both lenses, arched up over the beak between them
  const outline = (q, x0, x1, y0, y1, r, nw, nh) => {
    q.moveTo(x0 + r, y0); q.lineTo(x1 - r, y0); q.arcTo(x1, y0, x1, y0 + r, r); q.lineTo(x1, y1 - r); q.arcTo(x1, y1, x1 - r, y1, r);
    q.lineTo(nw, y1); q.quadraticCurveTo(0, y1 - 2 * nh, -nw, y1);
    q.lineTo(x0 + r, y1); q.arcTo(x0, y1, x0, y1 - r, r); q.lineTo(x0, y0 + r); q.arcTo(x0, y0, x0 + r, y0, r); q.closePath();
  };
  const body = (half, lw, lh, lr, gi, R, dy) => {
    const q = new Path2D(), outer = half + lw / 2;
    outline(q, -outer, outer, -lh / 2 + dy, lh / 2 + dy, lr, half - lw / 2 + R * 0.55, R * 0.62);
    for (const s of [-1, 1]) q.roundRect(s * half - lw / 2 + gi, -lh / 2 + gi + dy, lw - 2 * gi, lh - 2 * gi, lr * 0.75);
    return q;
  };
  window.DiveMask = {
    draw(c, anim, frame, cell) {
      const poses = window.SWIFTEE_MASK_ANCHORS && window.SWIFTEE_MASK_ANCHORS[anim];
      const p = poses && poses[frame];
      if (!p) return;
      const cx = p[0] * cell, cy = p[1] * cell, S = p[2] * cell, R = p[3] * cell, ang = p[4];
      const lw = R * 2.9, lh = R * 2.7, lr = lh * 0.42, rim = Math.max(1, R * 0.13); // a lens, round its eye
      const half = S / 2, outer = half + lw / 2;
      c.save();
      c.translate(cx, cy);
      c.rotate(ang);
      // the strap: round the back of her head, only where she is (source-atop), so it wraps rather than floats
      c.save();
      c.globalCompositeOperation = 'source-atop';
      const sy = -R * 0.1, sh = R * 0.62;
      const strap = c.createLinearGradient(0, sy - sh / 2, 0, sy + sh / 2);
      strap.addColorStop(0, '#2b6fb3'); strap.addColorStop(0.45, '#174a80'); strap.addColorStop(1, '#0d2f57');
      c.fillStyle = strap;
      c.fillRect(-outer - R * 6, sy - sh / 2, R * 6.2, sh);
      c.fillRect(outer - R * 0.2, sy - sh / 2, R * 6.2, sh);
      c.restore();
      // the contact shadow the frame casts on her face
      c.save();
      c.filter = 'blur(' + (R * 0.22).toFixed(2) + 'px)';
      c.fillStyle = 'rgba(0, 40, 70, 0.28)';
      const gi = R * 0.34;
      c.fill(body(half, lw, lh, lr, gi, R, R * 0.22), 'evenodd');
      c.restore();
      // the body: sunny yellow silicone with a darker rim round its outline and round each window
      const frameFill = c.createLinearGradient(0, -lh / 2, 0, lh / 2);
      frameFill.addColorStop(0, '#ffe066'); frameFill.addColorStop(0.55, '#ffc21a'); frameFill.addColorStop(1, '#f29a00');
      c.lineJoin = 'round';
      c.fillStyle = frameFill;
      c.strokeStyle = '#a85d00';
      c.lineWidth = rim;
      const b = body(half, lw, lh, lr, gi, R, 0);
      c.fill(b, 'evenodd');
      c.stroke(b);
      // the glass: tinted, see-through (her eyes and expressions show), with a soft inner shadow round its edge
      for (const s of [-1, 1]) {
        const gx = s * half - lw / 2 + gi, gy = -lh / 2 + gi, gw = lw - 2 * gi, gh = lh - 2 * gi;
        c.save();
        rr(c, gx, gy, gw, gh, lr * 0.75);
        const glass = c.createLinearGradient(gx, gy, gx + gw, gy + gh);
        glass.addColorStop(0, 'rgba(200, 245, 255, 0.34)'); glass.addColorStop(1, 'rgba(80, 190, 230, 0.22)');
        c.fillStyle = glass;
        c.fill();
        c.clip();
        c.strokeStyle = 'rgba(0, 60, 90, 0.35)';
        c.lineWidth = R * 0.22;
        rr(c, gx, gy, gw, gh, lr * 0.75);
        c.stroke();
        // the glare: a curved streak across the upper corner and a small dot
        c.strokeStyle = 'rgba(255, 255, 255, 0.85)';
        c.lineCap = 'round';
        c.lineWidth = R * 0.2;
        c.beginPath();
        c.arc(gx + gw * 0.62, gy + gh * 0.62, Math.min(gw, gh) * 0.48, Math.PI * 1.08, Math.PI * 1.42);
        c.stroke();
        c.fillStyle = 'rgba(255, 255, 255, 0.8)';
        c.beginPath();
        c.arc(gx + gw * 0.74, gy + gh * 0.24, R * 0.12, 0, TAU);
        c.fill();
        c.restore();
      }
      // a highlight along the top of the frame, the silicone's sheen
      c.strokeStyle = 'rgba(255, 255, 255, 0.55)';
      c.lineWidth = R * 0.1;
      c.lineCap = 'round';
      for (const s of [-1, 1]) {
        c.beginPath();
        c.moveTo(s * half - lw * 0.28, -lh / 2 + R * 0.14);
        c.lineTo(s * half + lw * 0.2, -lh / 2 + R * 0.14);
        c.stroke();
      }
      // the snorkel, clipped to the strap on her left, rising past her head
      const tx = -outer - R * 0.15, tw = R * 0.62;
      const tube = c.createLinearGradient(tx - tw / 2, 0, tx + tw / 2, 0);
      tube.addColorStop(0, '#ff8a2a'); tube.addColorStop(0.5, '#ffb04d'); tube.addColorStop(1, '#e56a00');
      c.strokeStyle = tube;
      c.lineWidth = tw;
      c.beginPath();
      c.moveTo(tx, R * 0.9);
      c.quadraticCurveTo(tx - R * 0.5, -R * 1.6, tx - R * 0.15, -R * 3.6);
      c.stroke();
      c.strokeStyle = 'rgba(255, 255, 255, 0.5)';
      c.lineWidth = tw * 0.22;
      c.beginPath();
      c.moveTo(tx + tw * 0.15, R * 0.6);
      c.quadraticCurveTo(tx - R * 0.35, -R * 1.6, tx, -R * 3.4);
      c.stroke();
      c.fillStyle = '#d95f00';
      c.beginPath();
      c.ellipse(tx - R * 0.15, -R * 3.6, tw * 0.62, tw * 0.3, -0.15, 0, TAU);
      c.fill();
      // the clip that holds it to the strap
      c.fillStyle = '#174a80';
      rr(c, tx - tw * 0.75, sy - sh * 0.55, tw * 1.5, sh * 1.1, R * 0.12);
      c.fill();
      c.restore();
    },
  };
})();
